llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Golidocitinib, the closest analogue, shares the aminopyrimidine-indole/azaindole core and a basic N-methylpiperazine; a radiolabeled human mass balance study concluded >80% oral bioavailability, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "CC-292, an acrylamide-aniline pyrimidine BTK inhibitor structurally analogous to the query's covalent warhead and pyrimidine core, showed excellent oral bioavailability in a human Phase IA study, directly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Imatinib, which shares the 2-arylaminopyrimidine scaffold and a basic N-methylpiperazine, has ~98% absolute oral bioavailability in humans, demonstrating that extensive ionization and a large polar surface do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Zongertinib, an acrylamide-containing kinase inhibitor with a pyrimidine/quinazoline-like core, was predicted to have 41% human oral bioavailability, above the 20% threshold and consistent with the query's covalent-inhibitor class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Flumatinib, an imatinib analogue with a similar aminopyrimidine and N-methylpiperazine, has low oral bioavailability in humans; however, its lower similarity and additional trifluoromethyl/benzamide features limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Nilotinib, a related 2-arylaminopyrimidine, can have absolute bioavailability near 17% under some conditions, indicating solubility-limited absorption in this scaffold class; but its lower similarity and different substitution pattern weaken direct transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable human evidence, especially from the closest analogue golidocitinib (>80% F) and the acrylamide-pyrimidine analogues CC-292 and zongertinib, supports high oral bioavailability (F≥20%). Low-F analogues such as flumatinib and nilotinib are less similar, and their solubility limitations are not clearly shared by the query. The physicochemical prior is low but is overridden by direct experimental evidence from structurally related kinase inhibitors.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data exist for the exact query molecule.",
    "Morgan similarities to the evidence molecules are moderate (0.24–0.35), leaving structural uncertainty.",
    "The impact of the strongly basic diamine side chain and high logP on solubility and efflux is not directly measured in the query.",
    "Nilotinib/flumatinib low-F mechanisms could transfer if the query is solubility-limited, but current evidence does not establish that."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

